    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_staff_bank_account PRIMARY KEY (id)
);
COMMENT ON TABLE payroll.staff_bank_account IS 'Bank account salary is paid into. The account number is stored encrypted and exposed masked.';
COMMENT ON COLUMN payroll.staff_bank_account.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN payroll.staff_bank_account.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
