COMMENT ON COLUMN payroll.staff_bank_account.account_holder_name IS 'Name on the account.';
COMMENT ON COLUMN payroll.staff_bank_account.account_number_enc IS 'Account number (application-encrypted envelope; write-only through the API).';
COMMENT ON COLUMN payroll.staff_bank_account.account_number_masked IS 'Masked display form (last 4).';
COMMENT ON COLUMN payroll.staff_bank_account.ifsc_code IS 'Bank routing code.';
COMMENT ON COLUMN payroll.staff_bank_account.bank_name IS 'Bank.';
COMMENT ON COLUMN payroll.staff_bank_account.branch_name IS 'Branch.';
COMMENT ON COLUMN payroll.staff_bank_account.is_primary IS 'Account currently used for disbursement.';
COMMENT ON COLUMN payroll.staff_bank_account.is_active IS 'Whether usable.';
COMMENT ON COLUMN payroll.staff_bank_account.created_at IS 'Row creation time.';
COMMENT ON COLUMN payroll.staff_bank_account.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
