COMMENT ON COLUMN payroll.staff_bank_account.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN payroll.staff_bank_account.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
