-- === Module-local infrastructure (distributed deployment: no cross-schema access) ===
CREATE TABLE payroll.idempotency_key (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    idempotency_key uuid NOT NULL,
    user_id uuid,
    operation_name varchar(120) NOT NULL,
    request_hash varchar(64),
    response_status smallint,
    response_body text,
    locked_at timestamptz,
    completed_at timestamptz,
    expires_at timestamptz NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_payroll_idempotency_key PRIMARY KEY (id),
    CONSTRAINT uq_payroll_idempotency_key_1 UNIQUE (tenant_id, idempotency_key)
);
COMMENT ON TABLE payroll.idempotency_key IS 'Module-local idempotency store of the payroll module: stored outcome of a write carrying an Idempotency-Key; replays return the stored response. Rows expire after 24h (cleanup job).';
COMMENT ON COLUMN payroll.idempotency_key.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN payroll.idempotency_key.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN payroll.idempotency_key.idempotency_key IS 'Key sent by the client.';
COMMENT ON COLUMN payroll.idempotency_key.user_id IS 'Caller.';
COMMENT ON COLUMN payroll.idempotency_key.operation_name IS 'Operation the key was used on.';
COMMENT ON COLUMN payroll.idempotency_key.request_hash IS 'Hash of the request body; a replay with a different body is rejected.';
COMMENT ON COLUMN payroll.idempotency_key.response_status IS 'Stored HTTP status.';
COMMENT ON COLUMN payroll.idempotency_key.response_body IS 'Stored response body.';
COMMENT ON COLUMN payroll.idempotency_key.locked_at IS 'Set while the first attempt is still executing.';
COMMENT ON COLUMN payroll.idempotency_key.completed_at IS 'When the stored response was written.';
COMMENT ON COLUMN payroll.idempotency_key.expires_at IS 'When the row may be purged.';
COMMENT ON COLUMN payroll.idempotency_key.created_at IS 'Row creation time.';
COMMENT ON COLUMN payroll.idempotency_key.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN payroll.idempotency_key.updated_at IS 'Last modification time (set by the application on every update).';
COMMENT ON COLUMN payroll.idempotency_key.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN payroll.idempotency_key.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
COMMENT ON COLUMN payroll.idempotency_key.row_version IS 'Optimistic-lock version, incremented on every update; used as the ETag.';
ALTER TABLE payroll.idempotency_key ENABLE ROW LEVEL SECURITY;
ALTER TABLE payroll.idempotency_key FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON payroll.idempotency_key USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
CREATE TABLE payroll.operation (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    operation_name varchar(120) NOT NULL,
    resource_type varchar(80),
    resource_id uuid,
    status varchar(20) NOT NULL DEFAULT 'running',
    progress_percent smallint,
    error_code varchar(60),
    error_message varchar(500),
    result_entity_type varchar(80),
    result_entity_id uuid,
    started_by_user_id uuid,
    started_at timestamptz NOT NULL DEFAULT now(),
    finished_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    result text,
    CONSTRAINT pk_payroll_operation PRIMARY KEY (id),
    CONSTRAINT ck_payroll_operation_status CHECK (status IN ('running', 'succeeded', 'failed', 'cancelled'))
);
COMMENT ON TABLE payroll.operation IS 'Module-local long-running operation record of the payroll module, returned by its async API calls; polled by clients until it finishes.';
COMMENT ON COLUMN payroll.operation.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN payroll.operation.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN payroll.operation.operation_name IS 'Operation id as exposed by the API (module.Method).';
COMMENT ON COLUMN payroll.operation.resource_type IS 'Kind of resource being worked on.';
COMMENT ON COLUMN payroll.operation.resource_id IS 'Id of that resource.';
COMMENT ON COLUMN payroll.operation.status IS 'running / succeeded / failed / cancelled.';
COMMENT ON COLUMN payroll.operation.progress_percent IS 'Progress, when the job reports it.';
COMMENT ON COLUMN payroll.operation.error_code IS 'Machine error code when failed.';
COMMENT ON COLUMN payroll.operation.error_message IS 'Human error summary when failed.';
COMMENT ON COLUMN payroll.operation.result_entity_type IS 'Kind of the produced record.';
COMMENT ON COLUMN payroll.operation.result_entity_id IS 'Id of the produced record.';
COMMENT ON COLUMN payroll.operation.started_by_user_id IS 'User who started it.';
COMMENT ON COLUMN payroll.operation.started_at IS 'Start time.';
COMMENT ON COLUMN payroll.operation.finished_at IS 'End time.';
COMMENT ON COLUMN payroll.operation.created_at IS 'Row creation time.';
COMMENT ON COLUMN payroll.operation.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN payroll.operation.updated_at IS 'Last modification time (set by the application on every update).';
COMMENT ON COLUMN payroll.operation.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN payroll.operation.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
COMMENT ON COLUMN payroll.operation.row_version IS 'Optimistic-lock version, incremented on every update; used as the ETag.';
COMMENT ON COLUMN payroll.operation.result IS 'Outcome of a finished operation as a JSON object (counts, skipped items); NULL while it runs and when it has none.';
ALTER TABLE payroll.operation ENABLE ROW LEVEL SECURITY;
ALTER TABLE payroll.operation FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON payroll.operation USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
CREATE TABLE payroll.number_sequence (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    institution_id uuid,
    sequence_code varchar(40) NOT NULL,
    period_key varchar(20) NOT NULL DEFAULT '',
    prefix varchar(20),
    padding smallint NOT NULL DEFAULT 6,
    next_value bigint NOT NULL DEFAULT 1,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_payroll_number_sequence PRIMARY KEY (id),
    CONSTRAINT uq_payroll_number_sequence_1 UNIQUE NULLS NOT DISTINCT (tenant_id, institution_id, sequence_code, period_key)
);
COMMENT ON TABLE payroll.number_sequence IS 'Module-local gap-aware number source of the payroll module (payslip numbers). Read with SELECT ... FOR UPDATE inside the issuing transaction; never shared with another module.';
COMMENT ON COLUMN payroll.number_sequence.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN payroll.number_sequence.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN payroll.number_sequence.institution_id IS 'Institution scope (NULL = tenant-wide sequence).';
COMMENT ON COLUMN payroll.number_sequence.sequence_code IS 'Which number series of this module (payslip numbers).';
COMMENT ON COLUMN payroll.number_sequence.period_key IS 'Reset period (fiscal year key such as FY2026; empty = never resets).';
COMMENT ON COLUMN payroll.number_sequence.prefix IS 'Rendered number prefix.';
COMMENT ON COLUMN payroll.number_sequence.padding IS 'Zero padding width of the numeric part.';
COMMENT ON COLUMN payroll.number_sequence.next_value IS 'Next number to issue.';
COMMENT ON COLUMN payroll.number_sequence.created_at IS 'Row creation time.';
COMMENT ON COLUMN payroll.number_sequence.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN payroll.number_sequence.updated_at IS 'Last modification time (set by the application on every update).';
COMMENT ON COLUMN payroll.number_sequence.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN payroll.number_sequence.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
COMMENT ON COLUMN payroll.number_sequence.row_version IS 'Optimistic-lock version, incremented on every update; used as the ETag.';
ALTER TABLE payroll.number_sequence ENABLE ROW LEVEL SECURITY;
ALTER TABLE payroll.number_sequence FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON payroll.number_sequence USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
CREATE INDEX ix_number_sequence_institution_id ON payroll.number_sequence (institution_id);

-- === Privacy tasks (design PRIVACY-AND-CONSENT-CENTRE §9.1, §10) and the module's scheduled jobs (core JobSchedule) ===
CREATE TABLE payroll.privacy_task_receipt (
    task_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    kind varchar(10) NOT NULL,
    payload jsonb NOT NULL,
    status varchar(15) NOT NULL DEFAULT 'received',
    result jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    completed_at timestamptz,
    CONSTRAINT pk_payroll_privacy_task_receipt PRIMARY KEY (task_id),
    CONSTRAINT ck_payroll_privacy_task_receipt_kind CHECK (kind IN ('task', 'retention')),
    CONSTRAINT ck_payroll_privacy_task_receipt_status CHECK (status IN ('received', 'done', 'partial', 'failed',
        'not_applicable')),
    CONSTRAINT ck_payroll_privacy_task_receipt_completed CHECK ((status = 'received') = (completed_at IS NULL))
);
COMMENT ON TABLE payroll.privacy_task_receipt IS 'The privacy tasks and retention runs privacy sent this module (privacy.rights_request.task_assigned, privacy.retention.due), one row per task or run id: a task dispatched again runs once, is retried after a failure and is answered again from the stored answer (privacy-client PrivacyTaskHandler). Ids, codes and counts only.';
COMMENT ON COLUMN payroll.privacy_task_receipt.task_id IS 'The rights-request task id or the retention run id privacy sent; the id the module answers with.';
COMMENT ON COLUMN payroll.privacy_task_receipt.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN payroll.privacy_task_receipt.kind IS 'task (a rights-request task) or retention (a retention run).';
COMMENT ON COLUMN payroll.privacy_task_receipt.payload IS 'The event''s data as privacy sent it: ids, codes and dates only.';
COMMENT ON COLUMN payroll.privacy_task_receipt.status IS 'received (waiting for the module''s job), done, partial, failed or not_applicable.';
COMMENT ON COLUMN payroll.privacy_task_receipt.result IS 'The answer published (<module>.privacy_task.completed or <module>.privacy_retention.completed): counts and codes; null while received.';
COMMENT ON COLUMN payroll.privacy_task_receipt.created_at IS 'When the task or run first arrived.';
COMMENT ON COLUMN payroll.privacy_task_receipt.completed_at IS 'When the module answered; null while received.';
CREATE INDEX ix_payroll_privacy_task_receipt_received ON payroll.privacy_task_receipt (tenant_id, created_at) WHERE status = 'received';
COMMENT ON INDEX payroll.ix_payroll_privacy_task_receipt_received IS 'The tasks and runs waiting for the module''s job, the oldest first.';
ALTER TABLE payroll.privacy_task_receipt ENABLE ROW LEVEL SECURITY;
ALTER TABLE payroll.privacy_task_receipt FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON payroll.privacy_task_receipt USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
CREATE TABLE payroll.job_schedule (
    job_code varchar(60) NOT NULL,
    tenant_id uuid NOT NULL,
    next_run_at timestamptz NOT NULL,
    lease_owner uuid,
    lease_until timestamptz,
    last_run_at timestamptz,
    failures integer NOT NULL DEFAULT 0,
    last_error varchar(500),
    CONSTRAINT pk_job_schedule PRIMARY KEY (job_code, tenant_id),
    CONSTRAINT ck_job_schedule_lease CHECK ((lease_owner IS NULL) = (lease_until IS NULL)),
    CONSTRAINT ck_job_schedule_failures CHECK (failures >= 0)
);
COMMENT ON TABLE payroll.job_schedule IS 'When each tenant is next due for each scheduled job of the module (core JobSchedule, ROADMAP ARC-4). A tenant is enrolled the first time it has work for the job. Job codes, tenant ids and times only, no personal data, and no row-level security: the job runner claims due rows across tenants, then runs each in its tenant''s own context.';
COMMENT ON COLUMN payroll.job_schedule.job_code IS 'The job (<module>.<name>): payroll.privacy_tasks (runs the privacy tasks and retention runs of payroll.privacy_task_receipt).';
COMMENT ON COLUMN payroll.job_schedule.tenant_id IS 'The tenant the job runs for.';
COMMENT ON COLUMN payroll.job_schedule.next_run_at IS 'When the tenant is next due.';
COMMENT ON COLUMN payroll.job_schedule.lease_owner IS 'The runner (a random id per process) holding the tenant''s run; null while no run is held.';
COMMENT ON COLUMN payroll.job_schedule.lease_until IS 'Until when the lease holds; after it another runner may take the run over.';
COMMENT ON COLUMN payroll.job_schedule.last_run_at IS 'When the last run ended, finished or failed.';
COMMENT ON COLUMN payroll.job_schedule.failures IS 'Failed runs in a row; the retry delay doubles with each.';
COMMENT ON COLUMN payroll.job_schedule.last_error IS 'Why the last run failed (exception class and message, first 500 characters); null after a finished run.';
CREATE INDEX ix_job_schedule_due ON payroll.job_schedule (next_run_at);
COMMENT ON INDEX payroll.ix_job_schedule_due IS 'The due runs, the longest overdue first.';

